/* Guided preview. No model-generated responses are claimed without an AI service. */
const stylistIcon="<svg\n  xmlns=\"http://www.w3.org/2000/svg\"\n  width=\"24\" aria-hidden=\"true\" focusable=\"false\" class=\"stylist-icon\"\n  height=\"24\"\n  viewBox=\"0 0 24 24\"\n  fill=\"none\"\n  stroke=\"currentColor\"\n  stroke-width=\"2\"\n  stroke-linecap=\"round\"\n  stroke-linejoin=\"round\"\n>\n  <path d=\"M12 9l-7.971 4.428a2 2 0 0 0 -1.029 1.749v.823a2 2 0 0 0 2 2h1\" />\n  <path d=\"M18 18h1a2 2 0 0 0 2 -2v-.823a2 2 0 0 0 -1.029 -1.749l-7.971 -4.428c-1.457 -.81 -1.993 -2.333 -2 -4a2 2 0 1 1 4 0\" />\n  <path d=\"M6 18a2 2 0 0 1 2 -2h8a2 2 0 0 1 2 2v1a2 2 0 0 1 -2 2h-8a2 2 0 0 1 -2 -2l0 -1\" />\n</svg>\n";
document.body.insertAdjacentHTML('beforeend',`<button class="stylist-launch" data-stylist aria-haspopup="dialog" aria-controls="stylistDialog">${stylistIcon}<span>Orí AI Stylist<small>Preview</small></span></button><dialog id="stylistDialog" class="stylist-dialog" aria-labelledby="stylistTitle"><div class="stylist-head"><div><span class="stylist-badge">YOUR PERSONAL EDIT</span><h2 id="stylistTitle">Orí AI Stylist</h2></div><button class="icon-button" data-close aria-label="Close stylist">${icon('x')}</button></div><div class="stylist-content"><p class="stylist-intro">A little help finding pieces that feel like you.</p><p class="stylist-preview">Guided preview · Live AI conversation is coming soon. These edits use your selections below.</p><form id="stylistForm"><fieldset><legend>What are you dressing for?</legend><div class="stylist-options">${[['everyday','Every day'],['evening','An evening out'],['celebration','A celebration']].map(([v,l],i)=>`<label><input type="radio" name="occasion" value="${v}" ${i===0?'checked':''}><span>${l}</span></label>`).join('')}</div></fieldset><fieldset><legend>Your mood</legend><div class="stylist-options">${[['minimal','Fine & delicate'],['bold','Sculptural gold'],['pearl','Pearls & colour']].map(([v,l],i)=>`<label><input type="radio" name="mood" value="${v}" ${i===0?'checked':''}><span>${l}</span></label>`).join('')}</div></fieldset><label class="stylist-budget" for="stylistBudget">Budget per piece</label><select name="budget" id="stylistBudget"><option value="40000">Up to ₦40,000</option><option value="50000">Up to ₦50,000</option><option value="100000">Explore all prices</option></select><button class="primary stylist-submit">Create my edit ${stylistIcon}</button></form><div id="stylistResults" role="region" aria-label="Your styling edit" aria-live="polite"></div></div></dialog>`);
const stylistDialog=document.getElementById('stylistDialog');let stylistOpener;
document.addEventListener('click',e=>{const trigger=e.target.closest('[data-stylist]');if(trigger){stylistOpener=trigger;stylistDialog.showModal();document.body.classList.add('stylist-open');}if(e.target.closest('.stylist-result'))stylistDialog.close();if(e.target===stylistDialog){const r=stylistDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)stylistDialog.close();}});
stylistDialog.addEventListener('close',()=>{document.body.classList.remove('stylist-open');stylistOpener?.focus();});
const stylingEdits={minimal:{everyday:['sol','lumi','halo','figaro'],evening:['lariat','linear','lumi','vow'],celebration:['vow','lumi','linear','muse']},bold:{everyday:['twist','orbit','crescent','halo'],evening:['drop','orbit','muse','ripple'],celebration:['emerald','twist','muse','shell']},pearl:{everyday:['river','pearl-ring','lumi','heirloom'],evening:['heirloom','pearl-ring','jade','drop'],celebration:['heirloom','coral','pearl-ring','amber']}};
document.getElementById('stylistForm').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target),budget=Number(data.get('budget')),mood=data.get('mood'),occasion=data.get('occasion');const ranked=stylingEdits[mood][occasion].map(id=>products.find(p=>p.id===id)).filter(Boolean).filter(p=>p.price<=budget);const chosen=ranked.slice(0,3);const notes={minimal:'Keep the silhouette simple. A fine necklace and a small gold detail work beautifully together.',bold:'Give one sculptural piece the spotlight, then balance it with a quieter shape.',pearl:'Let pearls or colour lead the look. Finish with a simple gold detail for balance.'};document.getElementById('stylistResults').innerHTML=`<div class="stylist-result-heading"><span class="stylist-badge">YOUR GUIDED EDIT</span><h3>${chosen.length?'A few pieces for you.':'Try a little more room.'}</h3><p>${chosen.length?notes[mood]:'This mood starts above your selected budget. Increase the budget, or try fine & delicate for more options.'}</p></div>${chosen.map(p=>`<a class="stylist-result" href="#product/${p.id}"><img src="assets/${p.image}" alt="${esc(p.name)}"><div><h4>${p.name}</h4><p>${p.material}</p><strong>${money(p.price)}</strong></div><span>View piece</span></a>`).join('')}`;document.getElementById('stylistResults').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'});});
/* Progressive enhancement: content is visible without this script. */
const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)');
const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');revealObserver.unobserve(entry.target);}}),{threshold:.08});
function enhanceMotion(){document.querySelectorAll('#app .product, #app .category-tile, #app .story, #app .section-head, #app .stylist-banner').forEach((el,i)=>{if(el.dataset.motion)return;el.dataset.motion='true';if(!reduceMotion.matches){el.classList.add('ori-reveal');el.style.setProperty('--reveal-delay',`${(i%3)*45}ms`);revealObserver.observe(el);}});}
new MutationObserver(enhanceMotion).observe(app,{childList:true});enhanceMotion();reduceMotion.addEventListener('change',()=>{if(reduceMotion.matches)document.querySelectorAll('.ori-reveal').forEach(el=>el.classList.add('is-visible'));});
